/* Broker workspace. All records remain in the existing browser-local demo store. */
const PRO_MENU=[['dashboard','grid','Ажлын самбар'],['listings','apartment','Миний зарууд'],['ledger','book-open','Хувийн бүртгэл'],['clients','users','Харилцагчид'],['consultations','message','Зөвлөгөө, лавлагаа'],['calendar','calendar','Ажлын хуваарь'],['contracts','file-text','Гэрээний бүртгэл'],['groups','network','Хамтын зуучлал'],['analytics','chart','Тайлан, үзүүлэлт'],['ads','megaphone','Зар сурталчилгаа'],['settings','settings','Байгууллагын мэдээлэл']];
const PRO_STATUS={published:'Нийтэлсэн',hidden:'Түр нуусан',closed:'Хэлцэл дууссан',new:'Шинэ',progress:'Ажиллаж байна',done:'Дууссан',draft:'Ноорог',negotiating:'Хэлэлцэж байна',signed:'Бүртгэл хаасан',cancelled:'Цуцалсан',planned:'Төлөвлөсөн',requested:'Хүсэлт хадгалсан'};
let proSearch='',proStatus='all',proMonthOffset=0,proDay='',proListingReturn=false;
function proState(){if(!flowState.pro||typeof flowState.pro!=='object'||Array.isArray(flowState.pro))flowState.pro={};const p=flowState.pro;for(const key of ['clients','consultations','schedules','contracts','ledger','groups','campaigns','activities'])if(!Array.isArray(p[key]))p[key]=[];if(!p.office||typeof p.office!=='object')p.office={name:'Өрөө зуучлал',agent:'',phone:'',email:'',address:'',registration:''};if(!p.inquiryMeta||typeof p.inquiryMeta!=='object')p.inquiryMeta={};return p}
function proToday(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Ulaanbaatar'}).format(new Date())}
function proDate(value){if(!value)return '—';return String(value).slice(0,10)}
function proOwned(){return flowState.listings}
function proActivities(){const ids=new Set(proOwned().map(h=>h.id));return proState().activities.filter(a=>!a.listingId||ids.has(a.listingId))}
function isPublicListing(h){return !!h&&adminCanPublish(h)&&(!h.local||!h.listingStatus||h.listingStatus==='published')}
function proStatusBadge(status){return `<span class="pro-status status-${esc(status||'new')}">${esc(PRO_STATUS[status]||status||'Шинэ')}</span>`}
function proClient(id){return proState().clients.find(c=>c.id===id)}
function proListing(id){return homes.find(h=>h.id===Number(id))}
function proClientName(id){return proClient(id)?.name||'Харилцагч сонгоогүй'}
function proListingName(id){return proListing(id)?.name||'Зар сонгоогүй'}
function proInquiries(){const ids=new Set(proOwned().map(h=>h.id));return flowState.requests.filter(r=>(ids.has(r.propertyId)||r.officeId==='broker-local')&&['message','phone'].includes(r.kind))}
function proLog(type,label,listingId=null){proState().activities.unshift({id:flowId(),type,label,listingId,date:new Date().toISOString()});proState().activities=proState().activities.slice(0,1000)}
function proTrackView(id){if(!homes.find(h=>h.id===id&&h.local))return;const p=proState(),last=p.activities.find(e=>e.type==='view'&&e.listingId===id);if(last&&Date.now()-Date.parse(last.date)<60000)return;proLog('view','Зар үзсэн',id);persistFlows()}
function proMutate(action,message){const before=JSON.stringify(proState());action(proState());if(!persistFlows()){flowState.pro=JSON.parse(before);return false}closeOverlay();render();if(message)toast(message);return true}
function proEmpty(title,copy,action=''){return `<div class="pro-empty">${icon('folder')}<h3>${title}</h3><p>${copy}</p>${action}</div>`}
function proAction(label,kind,preset={}){return `<button class="primary" onclick='proOpenEditor(${JSON.stringify(kind)},null,${esc(JSON.stringify(preset))})'>${icon('plus')}${label}</button>`}
function proToolbar(placeholder,extra=''){return `<form class="pro-toolbar" onsubmit="event.preventDefault();proSearch=this.elements.q.value.trim();render()"><div>${icon('search')}<input name="q" value="${esc(proSearch)}" placeholder="${placeholder}" aria-label="Бүртгэл хайх"><button>Хайх</button></div>${extra}</form>`}
function proMatch(item){return !proSearch||JSON.stringify(item).toLowerCase().includes(proSearch.toLowerCase())}
function proGo(tab){proSearch='';proStatus='all';goFlow('pro/'+tab)}
function proPage(tab='dashboard'){proState();if(tab==='')tab='dashboard';const valid=PRO_MENU.some(m=>m[0]===tab)||tab==='new';if(!valid)tab='dashboard';const title=tab==='new'?'Зар нэмэх':PRO_MENU.find(m=>m[0]===tab)?.[2];const page=tab==='dashboard'?proDashboard():tab==='listings'?proListings():tab==='clients'?proRecordsPage('clients'):tab==='ledger'?proRecordsPage('ledger'):tab==='consultations'?proConsultations():tab==='calendar'?proCalendar():tab==='contracts'?proRecordsPage('contracts'):tab==='groups'?proRecordsPage('groups'):tab==='ads'?proRecordsPage('campaigns'):tab==='analytics'?proAnalytics():tab==='office'?proOfficePage():tab==='settings'?proSettings():renderListingEditor();return `<div class="pro-shell"><aside class="pro-sidebar"><a class="pro-brand" href="#/pro"><img src="assets/oroo.png" alt="Өрөө"><b>PRO</b></a><div class="pro-workspace"><span class="pro-office-avatar">${icon('briefcase')}</span><div><b>${esc(proState().office.name||'Миний байгууллага')}</b>${brokerVerificationBadge('broker-local',true)}<span>Зуучлагчийн ажлын орон зай</span></div></div><div class="pro-nav-label">АЖЛЫН УДИРДЛАГА</div><nav class="pro-menu" aria-label="PRO цэс">${PRO_MENU.map(([key,glyph,label])=>`<a href="#/pro/${key}" onclick="proSearch='';proStatus='all'" ${key===tab||key==='listings'&&tab==='new'?'aria-current="page"':''}>${icon(glyph)}<span>${label}</span>${key==='consultations'&&proInquiries().filter(r=>(proState().inquiryMeta[r.id]?.stage||'new')==='new').length?'<b>'+proInquiries().filter(r=>(proState().inquiryMeta[r.id]?.stage||'new')==='new').length+'</b>':''}</a>`).join('')}</nav><div class="pro-sidebar-bottom"><a href="#/">${icon('arrow-up-right')}Хэрэглэгчийн сайт</a><div><span class="pro-live-dot"></span>Демо ажлын орчин<p>Энэ браузерт хадгална</p></div></div></aside><button class="pro-menu-dismiss" aria-label="PRO цэс хаах" onclick="document.querySelector('.pro-shell').classList.remove('menu-open')"></button><div class="pro-work"><header class="pro-header"><button class="pro-mobile-menu" aria-label="PRO цэс нээх" onclick="document.querySelector('.pro-shell').classList.toggle('menu-open')">${icon('menu')}</button><div><span>ӨРӨӨ PRO</span><b>${title}</b></div><div class="pro-header-actions"><span class="pro-date">${proToday()}</span>${tab==='new'?'<button class="pro-draft-save" onclick="saveListingDraftButton()" aria-label="Түр хадгалах">'+icon('bookmark')+'<span>Түр хадгалах</span></button>':''}<a href="#/pro/calendar" class="pro-icon-button" aria-label="Ажлын хуваарь">${icon('bell')}</a><button class="primary" onclick="proNewListing()">${icon('plus')}<span>Зар нэмэх</span></button><a class="pro-user" href="#/pro/settings" aria-label="Байгууллагын мэдээлэл">${icon('user')}</a></div></header><div class="pro-content">${brokerProBanner()}${page}<p class="pro-local-footer">Өрөө PRO · Демо хувилбар · Бүртгэл, тайлан зөвхөн энэ браузерын мэдээлэлд тулгуурлана.</p></div></div></div>`}
function proHeading(kicker,title,description,actions=''){return `<div class="pro-heading"><div><span class="pro-eyebrow">${kicker}</span><h1>${title}</h1><p>${description}</p></div><div class="pro-heading-actions">${actions}</div></div>`}
function proMetric(label,value,glyph,note,href){return `<a href="#/pro/${href}" class="pro-metric"><div><span>${label}</span><i>${icon(glyph)}</i></div><b>${value}</b><p>${note}</p></a>`}
function proChart(){const p=proState(),today=new Date(proToday()+'T12:00:00Z'),days=Array.from({length:7},(_,i)=>{const d=new Date(today);d.setUTCDate(d.getUTCDate()-6+i);return d.toISOString().slice(0,10)});const values=days.map(day=>proActivities().filter(e=>e.type==='view'&&new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Ulaanbaatar'}).format(new Date(e.date))===day).length),max=Math.max(1,...values);return `<div class="pro-chart" role="img" aria-label="Сүүлийн 7 хоногийн энэ браузерт бүртгэсэн зарын үзэлт: ${values.join(', ')}"><div class="pro-chart-grid"><span>${max}</span><span>${Math.round(max/2)}</span><span>0</span></div><div class="pro-chart-bars">${days.map((day,i)=>`<div><b>${values[i]}</b><i style="height:${Math.max(2,values[i]/max*130)}px" title="${day}: ${values[i]}"></i><span>${day.slice(5).replace('-','/')}</span></div>`).join('')}</div></div><div class="pro-chart-caption"><span><i></i>Зарын үзэлт</span><span>Нэг браузерын бүртгэл · Нэгдсэн серверийн статистик биш</span></div>`}
function proDashboard(){const p=proState(),own=proOwned(),published=own.filter(isPublicListing),pending=proInquiries().filter(r=>(p.inquiryMeta[r.id]?.stage||'new')!=='done'),upcoming=p.schedules.filter(s=>s.stage!=='done'&&s.date>=proToday()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));const today=upcoming.filter(s=>s.date===proToday());return `${proHeading('ТАНЫ ӨНӨӨДРИЙН АЖИЛ','Ажлаа нэг дороос удирдаарай','Зар, харилцагч, уулзалт — өдөр тутмын ажлын тань нэгдсэн самбар.',`<button onclick="proSeedWorkspace()">${icon('sparkles')}Жишээ мэдээлэл нэмэх</button>`)}<div class="pro-welcome"><div><span>ӨРӨӨ PRO · АЖЛЫН ТУСЛАХ</span><h2>Илүү цэгцтэй ажил.<br>Илүү ойр харилцагч.</h2><p>Зараа бүртгэж, лавлагаанаас уулзалт хүртэл<br>бүх алхмаа нэг орон зайд хөтлөөрэй.</p><button onclick="proNewListing()">Эхний зараа нэмэх ${icon('arrow-right')}</button></div><div class="pro-welcome-art" aria-hidden="true"><div>${icon('house')}<span></span></div><i>${icon('check')}</i><b>${icon('calendar')}</b></div></div><div class="pro-metrics">${proMetric('Нийтэлсэн зар',published.length,'apartment',own.length+' нийт зар · '+own.filter(h=>h.listingStatus==='hidden').length+' түр нуусан','listings')}${proMetric('Харилцагчид',p.clients.length,'users','Хүсэлт, сонирхол ба тэмдэглэл','clients')}${proMetric('Хүлээгдэж буй лавлагаа',pending.length,'message','Өөрийн зарын мессеж, утасны лавлагаа','consultations')}${proMetric('Өнөөдрийн хуваарь',today.length,'calendar',upcoming.length+' товлосон ажил','calendar')}</div><div class="pro-dashboard-grid"><section class="pro-panel pro-performance"><div class="pro-panel-head"><div><h2>Зарын сонирхол</h2><p>Сүүлийн 7 хоног</p></div><a href="#/pro/analytics">Тайлан харах ${icon('arrow-right')}</a></div>${proChart()}</section><section class="pro-panel pro-agenda"><div class="pro-panel-head"><div><h2>Ойрын ажлууд</h2><p>Таны уулзалт, сануулга</p></div><button class="pro-icon-button" onclick="proOpenEditor('schedules')" aria-label="Ажил нэмэх">${icon('plus')}</button></div>${upcoming.length?upcoming.slice(0,4).map(s=>`<a class="pro-agenda-row" href="#/pro/calendar"><span>${s.date.slice(5)}<b>${esc(s.time||'—')}</b></span><div><b>${esc(s.name)}</b><p>${esc(proClientName(s.clientId))}</p></div>${icon('chevron-right')}</a>`).join(''):proEmpty('Хуваарь тайван байна','Үзлэг, дуудлага эсвэл хийх ажлаа товлоорой.',proAction('Хуваарь нэмэх','schedules'))}</section><section class="pro-panel"><div class="pro-panel-head"><h2>Зарын төлөв</h2><a href="#/pro/listings">Бүгд ${icon('arrow-right')}</a></div><div class="pro-status-overview"><div class="pro-donut" style="--portion:${own.length?published.length/own.length*100:0}%"><b>${own.length}<span>нийт зар</span></b></div><div>${['published','hidden','closed'].map(status=>`<p><i class="status-dot ${status}"></i>${PRO_STATUS[status]}<b>${own.filter(h=>(h.listingStatus||'published')===status).length}</b></p>`).join('')}</div></div></section><section class="pro-panel"><div class="pro-panel-head"><h2>Сүүлд өөрчилсөн зарууд</h2><a href="#/pro/listings">Бүгд ${icon('arrow-right')}</a></div>${own.length?own.slice().sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt))).slice(0,3).map(h=>proMiniListing(h)).join(''):proEmpty('Таны анхны зар хүлээж байна','Оруулсан зар хэрэглэгчийн веб, мобайлд ижил мэдээллээр харагдана.','<button onclick="proNewListing()">Зар нэмэх</button>')}</section></div><div class="pro-start-grid">${[['ledger','book-open','Хувийн бүртгэл','Олон нийтэд гаргахаас өмнө хурдан тэмдэглэ.'],['clients','users','Харилцагчаа тань','Хүсэлт, төсөв, харилцааны түүхээ хөтөл.'],['contracts','file-text','Хэлцлээ цэгцэл','Хугацаа, төлбөр ба ажлын төлөвөө бүртгэ.']].map(([url,glyph,title,copy])=>`<a href="#/pro/${url}">${icon(glyph)}<div><h3>${title}</h3><p>${copy}</p></div>${icon('arrow-right')}</a>`).join('')}</div>`}
function proMiniListing(h){return `<div class="pro-mini-listing"><img src="${imageFor(h)}" alt="${esc(h.name)}"><div><b>${esc(h.name)}</b><span>${propertyPriceMarkup(h)}</span><p>${esc(h.area)} · ${h.size} м²</p></div><button onclick="proPreviewListing(${h.id})" aria-label="${esc(h.name)} урьдчилан харах">${icon('chevron-right')}</button></div>`}
function proListings(){const list=proOwned().filter(proMatch).filter(h=>proStatus==='all'||(h.listingStatus||'published')===proStatus);return `${proHeading('ЗАРЫН УДИРДЛАГА','Миний зарууд','Хэрэглэгчийн веб, мобайлтай нэг мэдээллээр холбогдоно.','<button class="primary" onclick="proNewListing()">'+icon('plus')+'Зар нэмэх</button>')}${proToolbar('Нэр, хаяг, зарын дугаар',`<select aria-label="Зарын төлөв" onchange="proStatus=this.value;render()">${[['all','Бүх төлөв'],...['published','hidden','closed'].map(s=>[s,PRO_STATUS[s]])].map(([v,l])=>`<option value="${v}" ${proStatus===v?'selected':''}>${l}</option>`).join('')}</select>`)}<div class="pro-panel"><div class="pro-table-wrap"><table class="pro-table"><thead><tr><th>Зарын мэдээлэл</th><th>Үнэ / Нөхцөл</th><th>Төлөв</th><th>Шинэчилсэн</th><th>Удирдах</th></tr></thead><tbody>${list.map(h=>`<tr><td><div class="pro-table-property"><img src="${imageFor(h)}" alt="Зарын зураг"><div><b>${esc(h.name)}</b><p>№ ${h.id} · ${esc(h.area)}</p><span>${h.size} м² · ${listingFloorText(h)}</span></div></div></td><td><b>${propertyPriceMarkup(h)}</b><p>СӨХ ${listingFeeText(h)}</p></td><td>${proStatusBadge(h.listingStatus||'published')}${adminProListingStatus(h)}</td><td>${proDate(h.updatedAt||h.createdAt)}</td><td><div class="pro-row-actions"><button onclick="editLocalListing(${h.id},'pro/listings')">${icon('file-text')}Засах</button><button onclick="previewSavedListingLocation(${h.id})">${icon('pin')}Байршил</button><button onclick="proPreviewListing(${h.id})">${icon('eye')}Харах</button><select aria-label="${esc(h.name)} төлөв" onchange="proSetListingStatus(${h.id},this.value)">${['published','hidden','closed'].map(s=>`<option value="${s}" ${(h.listingStatus||'published')===s?'selected':''}>${PRO_STATUS[s]}</option>`).join('')}</select></div></td></tr>`).join('')}</tbody></table></div>${!list.length?proEmpty('Зар олдсонгүй','Хайлт, төлөвөө өөрчлөх эсвэл анхны зараа бүртгээрэй.','<button class="primary" onclick="proNewListing()">'+icon('plus')+'Зар нэмэх</button>'):''}</div>`}
function proNewListing(ledgerId){const p=proState(),entry=p.ledger.find(l=>l.id===ledgerId);const current=flowState.draft||{};if(entry&&Object.keys(current).length&&!current.editId){modal('<h2>Түр хадгалсан зар байна</h2><p>Одоогийн зарын мэдээллээ дуусгаад хувийн бүртгэлээ зар болгоно уу.</p><button class="primary" onclick="closeOverlay();proNewListing()">Үргэлжлүүлэх</button>');return}if(entry){flowState.draft={...listingDraftDefaults(),name:entry.name,address:entry.address||'',area:entry.area||areas[0],price:String(entry.price||''),description:entry.note||'',desc:entry.name,contactName:p.office.agent||'',contactRole:'agent',agencyName:p.office.name||''};listingStep=0;editorReady=false;listingPhotoDraft=[]}if(!Object.keys(flowState.draft||{}).length){flowState.draft={...listingDraftDefaults(),contactRole:'agent',contactName:p.office.agent||'',agencyName:p.office.name||''};listingStep=0;listingPhotoDraft=[];editorReady=false}flowState.draft.returnTo='pro/listings';flowState.draft.proManaged=true;persistFlows();goFlow('pro/new')}
function proSetListingStatus(id,status){if(!['published','hidden','closed'].includes(status))return;const at=flowState.listings.findIndex(h=>h.id===id);if(at<0)return;const previous=flowState.listings[at],updated={...previous,listingStatus:status,updatedAt:new Date().toISOString()};flowState.listings[at]=updated;if(!persistFlows()){flowState.listings[at]=previous;render();return}const i=homes.findIndex(h=>h.id===id);if(i>=0)homes[i]=updated;proLog('listing_status',previous.name+' · '+PRO_STATUS[status],id);persistFlows();render();toast('Зарын төлөв шинэчлэгдлээ')}
function proPreviewListing(id){const h=flowState.listings.find(h=>h.id===id);if(!h)return;modal(`<div class="pro-preview"><span class="pro-eyebrow">ЗАРЫН УРЬДЧИЛСАН ХАРАГДАЦ</span><h2>${esc(h.name)}</h2>${proStatusBadge(h.listingStatus||'published')}<img src="${imageFor(h)}" alt="Зарын нүүр зураг"><h3>${propertyPriceMarkup(h)}</h3><p>${esc(h.desc)}</p>${listingPriceRows(h)}${listingInfoRows(h)}${listingEquipment(h)}${listingOptionChips(listingOptionLabels(h,'security'))}<p class="listing-user-text">${esc(h.description||'')}</p>${isPublicListing(h)?`<button class="primary" onclick="closeOverlay();detail(${id})">Хэрэглэгчийн хуудсыг харах ${icon('external-link')}</button>`:'<p class="notice">Энэ зар хэрэглэгчийн хайлт, жагсаалтад харагдахгүй.</p>'}</div>`);document.querySelector('.modal').classList.add('pro-preview-modal')}
const PRO_SCHEMAS={
 clients:{title:'Харилцагч',plural:'Харилцагчид',copy:'Хүсэлт, төсөв болон холбоо барих мэдээллээ нэг дор хадгалаарай.',fields:[['name','Харилцагчийн нэр','text',true],['phone','Утас','tel'],['email','Имэйл','email'],['kind','Харилцагчийн төрөл','select',true,[['tenant','Түрээслэгч'],['buyer','Худалдан авагч'],['owner','Өмчлөгч'],['seller','Худалдагч']]],['stage','Харилцааны төлөв','select',true,[['new','Шинэ'],['progress','Ажиллаж байна'],['done','Дууссан']]],['area','Сонирхсон дүүрэг','area'],['budgetMin','Доод төсөв, ₮','money'],['budgetMax','Дээд төсөв, ₮','money'],['note','Тэмдэглэл','textarea']]},
 consultations:{title:'Зөвлөгөө',plural:'Зөвлөгөөний бүртгэл',fields:[['name','Зөвлөгөөний гарчиг','text',true],['clientId','Харилцагч','client'],['newClientName','Шинэ харилцагчийн нэр','text'],['newClientPhone','Шинэ харилцагчийн утас','tel'],['listingId','Холбоотой зар','listing'],['stage','Төлөв','select',true,[['new','Шинэ'],['progress','Ажиллаж байна'],['done','Дууссан']]],['note','Хүсэлт / Зөвлөгөөний тэмдэглэл','textarea',true]]},
 schedules:{title:'Ажил, уулзалт',plural:'Ажлын хуваарь',fields:[['name','Ажлын нэр','text',true],['date','Огноо','date',true],['time','Цаг','time',true],['clientId','Харилцагч','client'],['listingId','Холбоотой зар','listing'],['kind','Ажлын төрөл','select',true,[['viewing','Байр үзүүлэх'],['call','Дуудлага'],['meeting','Уулзалт'],['payment','Төлбөрийн сануулга'],['other','Бусад']]],['stage','Төлөв','select',true,[['planned','Төлөвлөсөн'],['done','Дууссан'],['cancelled','Цуцалсан']]],['note','Тэмдэглэл','textarea']]},
 contracts:{title:'Гэрээний ажлын бүртгэл',plural:'Гэрээний бүртгэл',copy:'Хэлцлийн төлөв, хугацаа болон төлбөрийн товыг хөтөлнө. Энэ нь гарын үсэгтэй гэрээ, хууль зүйн маягт биш.',fields:[['name','Хэлцлийн нэр','text',true],['clientId','Харилцагч','client',true],['listingId','Холбоотой зар','listing',true],['kind','Гэрээний төрөл','select',true,[['rent','Түрээс'],['sale','Худалдах']]],['amount','Үндсэн үнэ, ₮','money',true],['deposit','Барьцаа, ₮','money'],['startDate','Эхлэх огноо','date',true],['endDate','Дуусах огноо','date'],['paymentDate','Дараагийн төлбөрийн огноо','date'],['stage','Ажлын төлөв','select',true,[['draft','Ноорог'],['negotiating','Хэлэлцэж байна'],['signed','Бүртгэл хаасан'],['cancelled','Цуцалсан']]],['note','Нөхцөл / Тэмдэглэл','textarea']]},
 ledger:{title:'Хувийн бүртгэл',plural:'Хувийн бүртгэл',copy:'Эхний мэдээллээ хурдан хадгалаарай. Эдгээр тэмдэглэл хэрэглэгчийн сайт дээр нийтлэгдэхгүй.',fields:[['name','Үл хөдлөхийн нэр','text',true],['area','Дүүрэг','area',true],['address','Хаяг','text'],['price','Санал болгох үнэ, ₮','money'],['contact','Өмчлөгчийн холбоо барих мэдээлэл','text'],['note','Тэмдэглэл','textarea']]},
 groups:{title:'Хамтын зуучлалын бүлэг',plural:'Хамтын зуучлал',copy:'Энэ браузерт ажлын бүлэг, гишүүний нэр ба хуваалцах зарын жагсаалтаа хөтөлнө. Бусад агенттай шууд холбогдох үйлчилгээ хараахан холбогдоогүй.',fields:[['name','Бүлгийн нэр','text',true],['area','Дүүрэг','area'],['members','Гишүүдийн нэр','text'],['visibility','Төлөвлөсөн бүлгийн төрөл','select',true,[['private','Хаалттай'],['public','Нээлттэй']]],['listingIds','Холбоотой зарууд','listings'],['note','Бүлгийн тэмдэглэл','textarea']]},
 campaigns:{title:'Зар сурталчилгааны хүсэлт',plural:'Зар сурталчилгаа',copy:'Хүсэлт админы хяналтад орно. Баталсан сурталчилгаа хугацаандаа энэ браузерын онцлох хэсэгт харагдана. Төлбөр холбогдоогүй.',fields:[['name','Аяны нэр','text',true],['kind','Бүтээгдэхүүн','select',true,[['general','Ердийн зар'],['package','Багц үйлчилгээ'],['premium','Премиум зар']]],['area','Байршуулах дүүрэг','area',true],['listingIds','Байршуулах зарууд','listings',true],['budget','Төлөвлөсөн төсөв, ₮','money',true],['startDate','Эхлэх огноо','date',true],['endDate','Дуусах огноо','date',true],['stage','Хүсэлтийн төлөв','select',true,[['draft','Ноорог'],['requested','Хүсэлт хадгалсан']]],['note','Тэмдэглэл','textarea']]}
};
function proField(field,item){const [name,label,type,required,choices]=field,value=item[name]??'',id='pro-'+name,attrs=`id="${id}" name="${name}" ${required?'required':''}`;let input='';if(['select','area','client','listing'].includes(type)){const options=type==='area'?areas.map(v=>[v,v]):type==='client'?proState().clients.map(c=>[c.id,c.name]):type==='listing'?proOwned().map(h=>[String(h.id),h.name]):choices;input=`<select ${attrs}><option value="">Сонгоно уу</option>${options.map(([key,text])=>`<option value="${esc(key)}" ${String(value)===String(key)?'selected':''}>${esc(text)}</option>`).join('')}</select>`}else if(type==='textarea')input=`<textarea ${attrs} maxlength="2000" rows="4">${esc(value)}</textarea>`;else if(type==='listings')input=`<div class="pro-listing-checks">${proOwned().length?proOwned().map(h=>`<label><input type="checkbox" name="listingIds" value="${h.id}" ${(item.listingIds||[]).includes(h.id)?'checked':''}>${esc(h.name)}</label>`).join(''):'<p>Эхлээд өөрийн зараа бүртгэнэ үү.</p>'}</div>`;else input=`<input ${attrs} type="${type==='money'?'number':type}" value="${esc(value)}" ${type==='money'?'min="0" max="1000000000000" step="1"':'maxlength="160"'}>`;return `<${type==='listings'?'div':'label'} class="pro-field ${['textarea','listings'].includes(type)?'wide':''}" ${type==='listings'?'':'for="'+id+'"'}><span>${label}${required?'<em>*</em>':''}</span>${input}</${type==='listings'?'div':'label'}>`}
function proOpenEditor(kind,id=null,preset={}){const schema=PRO_SCHEMAS[kind];if(!schema)return;const existing=id?proState()[kind].find(r=>r.id===id):null;const item={date:proDay||proToday(),time:'10:00',stage:kind==='schedules'?'planned':kind==='contracts'||kind==='campaigns'?'draft':'new',...preset,...existing};modal(`<div class="pro-form-header"><span class="pro-eyebrow">ӨРӨӨ PRO</span><h2>${schema.title}${id?' засах':' нэмэх'}</h2>${schema.copy?'<p>'+schema.copy+'</p>':''}</div><form class="pro-record-form" onsubmit="proSubmitRecord(event,'${kind}','${id||''}')">${preset.sourceRequestId?`<input type="hidden" name="sourceRequestId" value="${esc(preset.sourceRequestId)}">`:''}<div class="pro-form-grid">${schema.fields.map(f=>proField(f,item)).join('')}</div><p class="pro-form-error" role="alert"></p><div class="flow-actions"><button type="button" onclick="closeOverlay()">Буцах</button><button class="primary" type="submit">Хадгалах</button></div></form>`);document.querySelector('.modal').classList.add('pro-record-modal')}
function proValidate(kind,item){const schema=PRO_SCHEMAS[kind],errors=[];if(kind==='campaigns'&&item.stage==='requested'&&!brokerEligible())errors.push('Байгууллагын хоёр шатны хяналт дууссаны дараа сурталчилгааны хүсэлт илгээнэ үү.');for(const [key,label,type,required,options] of schema.fields){const value=item[key];if(required&&(value===undefined||value===null||value===''||Array.isArray(value)&&!value.length))errors.push(label+' оруулна уу.');if(type==='money'&&value!==''&&value!==undefined&&(!Number.isFinite(Number(value))||Number(value)<0||Number(value)>1e12))errors.push(label+' зөв тоо оруулна уу.');if(type==='select'&&value&&!options.some(([k])=>k===value))errors.push(label+' сонгоно уу.');if(type==='client'&&value&&!proClient(value))errors.push('Харилцагч олдсонгүй.');if(type==='listing'&&value&&!proOwned().some(h=>h.id===Number(value)))errors.push('Өөрийн зар сонгоно уу.');if(type==='date'&&value&&(!/^\d{4}-\d{2}-\d{2}$/.test(value)||!Number.isFinite(Date.parse(value))))errors.push(label+' шалгана уу.')}for(const key of ['phone','newClientPhone'])if(item[key]&&!/^\+?[\d\s()-]{8,25}$/.test(item[key]))errors.push('Утасны дугаар шалгана уу.');if(item.budgetMax&&Number(item.budgetMax)<Number(item.budgetMin||0))errors.push('Дээд төсөв доод төсвөөс бага байж болохгүй.');if(item.endDate&&item.startDate&&item.endDate<item.startDate)errors.push('Дуусах огноо эхлэх огнооноос өмнө байна.');if(item.listingIds?.some(id=>!proOwned().some(h=>h.id===id)))errors.push('Холбоотой зар олдсонгүй.');if(kind==='consultations'&&!item.clientId&&!item.newClientName)errors.push('Харилцагч сонгох эсвэл шинэ харилцагчийн нэр оруулна уу.');return errors}
function proSubmitRecord(event,kind,id){event.preventDefault();const schema=PRO_SCHEMAS[kind],f=new FormData(event.target),item={};for(const [name,,type] of schema.fields)item[name]=type==='listings'?f.getAll(name).map(Number):String(f.get(name)||'').trim();const errors=proValidate(kind,item);if(errors.length){event.target.querySelector('.pro-form-error').textContent=errors.join(' ');return}for(const [name,,type] of schema.fields)if(type==='money')item[name]=item[name]===''?null:Number(item[name]);const sourceRequestId=f.get('sourceRequestId');proMutate(p=>{if(kind==='consultations'&&!item.clientId&&item.newClientName){const client={id:flowId(),name:item.newClientName,phone:item.newClientPhone,stage:'new',kind:'tenant',note:'Зөвлөгөөнөөс бүртгэсэн',createdAt:new Date().toISOString()};p.clients.unshift(client);item.clientId=client.id}delete item.newClientName;delete item.newClientPhone;const at=p[kind].findIndex(r=>r.id===id),old=p[kind][at];const record={...old,...item,id:old?.id||flowId(),createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};if(kind==='campaigns')adminCampaignSaved(record,old);if(at>=0)p[kind][at]=record;else p[kind].unshift(record);if(sourceRequestId)p.inquiryMeta[sourceRequestId]={...p.inquiryMeta[sourceRequestId],stage:'progress',consultationId:record.id};proLog('record',schema.title+' · '+record.name)},'Бүртгэл хадгалагдлаа')}
function proConfirmDelete(kind,id){const record=proState()[kind]?.find(r=>r.id===id);if(!record)return;modal(`<h2>Бүртгэл хасах уу?</h2><p>${esc(record.name)}</p><p class="notice">Бусад бүртгэлийн холбоос нэргүй болж болно. Хассан бичлэгийг буцааж сэргээх боломжгүй.</p><div class="flow-actions"><button onclick="closeOverlay()">Буцах</button><button class="primary" onclick="proDeleteRecord('${kind}','${id}')">Хасах</button></div>`)}
function proDeleteRecord(kind,id){if(!PRO_SCHEMAS[kind])return;if(kind==='clients'&&['consultations','schedules','contracts'].some(key=>proState()[key].some(r=>r.clientId===id))){toast('Холбоотой зөвлөгөө, хуваарь эсвэл гэрээний бүртгэлийг эхлээд өөрчилнө үү.');return}proMutate(p=>{p[kind]=p[kind].filter(r=>r.id!==id)},'Бүртгэл хасагдлаа')}
function proRecordActions(kind,item){return `<div class="pro-row-actions"><button onclick="proOpenEditor('${kind}','${item.id}')">${icon('file-text')}Засах</button><button aria-label="${esc(item.name)} хасах" onclick="proConfirmDelete('${kind}','${item.id}')">${icon('trash')}</button></div>`}
function proRecordsPage(kind){const schema=PRO_SCHEMAS[kind],items=proState()[kind].filter(proMatch);return `${proHeading('АЖЛЫН БҮРТГЭЛ',schema.plural,schema.copy||'Харилцагчийн хүсэлт, тэмдэглэл ба ажлын явцыг хадгална.',proAction(schema.title+' нэмэх',kind))}${proToolbar('Нэр, тэмдэглэлээр хайх',`<button type="button" onclick="proExport('${kind}')">${icon('download')}CSV татах</button>`)}<div class="pro-record-grid ${kind==='clients'?'pro-client-grid':''}">${items.map(item=>proRecordCard(kind,item)).join('')}</div>${!items.length?'<div class="pro-panel">'+proEmpty('Одоогоор бүртгэл алга','Шинэ бүртгэл нэмж ажлаа эхлүүлээрэй.',proAction('Бүртгэл нэмэх',kind))+'</div>':''}`}
function proRecordCard(kind,item){let body='';if(kind==='clients')body=`<div class="pro-client-avatar">${esc(item.name[0]||'Х')}</div><p>${esc(item.phone||'Утас оруулаагүй')}${item.email?'<br>'+esc(item.email):''}</p><div class="pro-card-meta"><span>${esc(item.area||'Бүх дүүрэг')}</span><b>${item.budgetMax?formatMnt(item.budgetMax):'Төсөв оруулаагүй'}</b></div><div class="pro-card-links"><button onclick='proOpenEditor("consultations",null,${JSON.stringify({clientId:item.id})})'>Зөвлөгөө</button><button onclick='proOpenEditor("schedules",null,${JSON.stringify({clientId:item.id})})'>Уулзалт</button><button onclick='proOpenEditor("contracts",null,${JSON.stringify({clientId:item.id})})'>Хэлцэл</button></div>`;else if(kind==='ledger')body=`<p>${esc(item.area||'')} · ${esc(item.address||'Хаяг оруулаагүй')}</p><h3 class="pro-card-money">${item.price?formatMnt(item.price):'Үнэ тохиролцоно'}</h3><p>${esc(item.contact||'Холбоо барих мэдээлэл оруулаагүй')}</p><button class="pro-text-button" onclick="proNewListing('${item.id}')">Дэлгэрэнгүй зар болгох ${icon('arrow-right')}</button>`;else if(kind==='contracts')body=`<p>${esc(proClientName(item.clientId))}<br>${esc(proListingName(item.listingId))}</p><h3 class="pro-card-money">${formatMnt(item.amount)}</h3><div class="pro-card-meta"><span>${proDate(item.startDate)} → ${proDate(item.endDate)}</span></div>${item.paymentDate?'<p>Төлбөрийн тов: '+esc(item.paymentDate)+'</p>':''}<button class="pro-text-button" onclick="proPrintContract('${item.id}')">${icon('printer')}Ажлын бүртгэл хэвлэх</button>`;else if(kind==='groups')body=`<p>${esc(item.area||'Бүх дүүрэг')} · ${item.visibility==='public'?'Нээлттэй бүлгийн төлөвлөгөө':'Хаалттай бүлгийн төлөвлөгөө'}</p><p>${esc(item.members||'Гишүүний нэр оруулаагүй')}</p><div class="pro-linked-listings">${(item.listingIds||[]).map(id=>`<button onclick="proPreviewListing(${id})">${icon('apartment')}${esc(proListingName(id))}</button>`).join('')||'Холбоотой зар алга'}</div>`;else if(kind==='campaigns')body=`<p>${esc(item.area)} · ${esc({general:'Ердийн зар',package:'Багц үйлчилгээ',premium:'Премиум зар'}[item.kind]||item.kind)}</p><h3 class="pro-card-money">${formatMnt(item.budget)}</h3><p>${proDate(item.startDate)} → ${proDate(item.endDate)}<br>${(item.listingIds||[]).length} зарын хүсэлт</p>`;return `<article class="pro-panel pro-record-card"><div class="pro-card-top">${kind==='clients'?icon('user'):icon(kind==='contracts'?'file-text':kind==='ledger'?'book-open':kind==='groups'?'network':'megaphone')}${item.stage?proStatusBadge(item.stage):'<span class="pro-private-label">Ажлын тэмдэглэл</span>'}</div><h2>${esc(item.name)}</h2>${body}${kind==='campaigns'?adminProCampaignStatus(item):''}${item.note?'<p class="pro-note">'+esc(item.note)+'</p>':''}${proRecordActions(kind,item)}</article>`}
function proConsultations(){const p=proState(),requests=proInquiries().filter(proMatch),records=p.consultations.filter(proMatch);return `${proHeading('ХАРИЛЦАГЧИЙН ҮЙЛЧИЛГЭЭ','Зөвлөгөө, лавлагаа','Хэрэглэгчийн лавлагааг зөвлөгөө, уулзалттай холбоорой.',proAction('Зөвлөгөө бүртгэх','consultations'))}${proToolbar('Зарын дугаар, зөвлөгөөний тэмдэглэл')}<section class="pro-panel"><div class="pro-panel-head"><h2>Миний зарын лавлагаа <span>${requests.length}</span></h2></div>${requests.length?requests.map(r=>`<div class="pro-inquiry"><span class="pro-inquiry-icon">${icon(r.kind==='phone'?'phone':'message')}</span><div><b>${esc(officeInquiryTitle(r))}</b><p>${esc(r.body)}</p><span>${esc(r.date)} · ${r.propertyId?'№ '+r.propertyId:'Байгууллагын лавлагаа'}</span></div><div class="pro-inquiry-actions"><select aria-label="Лавлагааны төлөв" onchange="proSetInquiry('${r.id}',this.value)">${['new','progress','done'].map(s=>`<option value="${s}" ${(p.inquiryMeta[r.id]?.stage||'new')===s?'selected':''}>${PRO_STATUS[s]}</option>`).join('')}</select><button onclick='proOpenEditor("consultations",null,${esc(JSON.stringify({name:'Зарын лавлагаа',listingId:r.propertyId?String(r.propertyId):'',note:r.body,sourceRequestId:r.id}))})'>Харилцагчтай холбох ${icon('arrow-right')}</button></div></div>`).join(''):proEmpty('Шинэ лавлагаа алга','Өөрийн нийтэлсэн зар дээр ирсэн лавлагаанууд энд харагдана.')}</section><div class="pro-section-title"><h2>Зөвлөгөөний түүх</h2></div><div class="pro-record-grid">${records.map(c=>`<article class="pro-panel pro-record-card"><div class="pro-card-top">${icon('message')}${proStatusBadge(c.stage)}</div><h2>${esc(c.name)}</h2><p>${esc(proClientName(c.clientId))}<br>${esc(proListingName(c.listingId))}</p><p class="pro-note">${esc(c.note)}</p><button class="pro-text-button" onclick='proOpenEditor("schedules",null,${JSON.stringify({clientId:c.clientId,listingId:c.listingId})})'>${icon('calendar')}Уулзалт товлох</button>${proRecordActions('consultations',c)}</article>`).join('')}</div>`}
function proSetInquiry(id,stage){if(!['new','progress','done'].includes(stage)||!proInquiries().some(r=>r.id===id))return;proMutate(p=>p.inquiryMeta[id]={...p.inquiryMeta[id],stage},'Лавлагааны төлөв хадгалагдлаа')}
function proCalendar(){const p=proState(),now=new Date(proToday()+'T12:00:00Z');now.setUTCDate(1);now.setUTCMonth(now.getUTCMonth()+proMonthOffset);const first=new Date(now),month=now.toISOString().slice(0,7),offset=(first.getUTCDay()+6)%7;first.setUTCDate(1-offset);const selected=proDay||proToday(),items=p.schedules.filter(s=>s.date===selected).sort((a,b)=>a.time.localeCompare(b.time));return `${proHeading('АЖЛЫН ХУВААРЬ','Ажлын хуваарь','Үзлэг, уулзалт, дуудлага болон төлбөрийн сануулгаа товлоорой.',proAction('Ажил нэмэх','schedules'))}<div class="pro-calendar-layout"><section class="pro-panel"><div class="pro-panel-head"><div class="pro-month-switch"><button aria-label="Өмнөх сар" onclick="proMonthOffset--;render()">${icon('chevron-left')}</button><h2>${month.replace('-',' / ')}</h2><button aria-label="Дараах сар" onclick="proMonthOffset++;render()">${icon('chevron-right')}</button></div><button onclick="proMonthOffset=0;proDay=proToday();render()">Өнөөдөр</button></div><div class="pro-calendar-week">${['Да','Мя','Лх','Пү','Ба','Бя','Ня'].map(day=>`<span>${day}</span>`).join('')}</div><div class="pro-calendar-days">${Array.from({length:42},(_,i)=>{const day=new Date(first);day.setUTCDate(first.getUTCDate()+i);const key=day.toISOString().slice(0,10),events=p.schedules.filter(s=>s.date===key&&s.stage!=='cancelled');return `<button class="${key===selected?'selected':''} ${key===proToday()?'today':''} ${key.slice(0,7)!==month?'outside':''}" aria-label="${key}, ${events.length} ажил" onclick="proDay='${key}';render()"><b>${day.getUTCDate()}</b>${events.slice(0,2).map(s=>`<span>${esc(s.time)} ${esc(s.name)}</span>`).join('')}${events.length>2?'<small>+'+(events.length-2)+'</small>':''}</button>`}).join('')}</div></section><section class="pro-panel"><div class="pro-panel-head"><h2>${selected}</h2><button class="pro-icon-button" onclick="proOpenEditor('schedules')" aria-label="Сонгосон өдөр ажил нэмэх">${icon('plus')}</button></div>${items.length?items.map(s=>`<article class="pro-schedule-item"><span>${esc(s.time)} ${proStatusBadge(s.stage)}</span><h3>${esc(s.name)}</h3><p>${esc(proClientName(s.clientId))}<br>${esc(proListingName(s.listingId))}</p>${s.note?'<p>'+esc(s.note)+'</p>':''}${proRecordActions('schedules',s)}</article>`).join(''):proEmpty('Товлосон ажил алга','Энэ өдрийн хийх ажлаа нэмээрэй.',proAction('Ажил нэмэх','schedules'))}</section></div><div class="pro-reminder-note">${icon('bell')}Сануулга энэ ажлын самбарт харагдана. SMS болон төхөөрөмжийн push мэдэгдэл илгээхгүй.</div>`}
function proAnalytics(){const p=proState(),views=proActivities().filter(a=>a.type==='view').length,own=proOwned(),inquiries=proInquiries();return `${proHeading('ТАЙЛАН, ҮЗҮҮЛЭЛТ','Тайлан, үзүүлэлт','Энэ браузерт бүртгэсэн үйлдэл, өөрийн зар ба харилцагчийн мэдээлэл.',`<button onclick="proExport('activities')">${icon('download')}Үйлдлийн CSV</button>`)}<div class="pro-metrics">${proMetric('Зарын үзэлт',views,'eye','60 секундэд давтагдсан нээлтийг нэгээр тоолно','listings')}${proMetric('Өөрийн зарын лавлагаа',inquiries.length,'message','Мессеж болон утасны лавлагаа','consultations')}${proMetric('Харилцагчид',p.clients.length,'users','Энэ ажлын орон зайн бүртгэл','clients')}${proMetric('Гэрээний бүртгэл',p.contracts.length,'file-text','Гарын үсэг, төлбөр баталгаажуулахгүй','contracts')}</div><section class="pro-panel"><div class="pro-panel-head"><h2>Сүүлийн 7 хоногийн үзэлт</h2></div>${proChart()}</section><section class="pro-panel"><div class="pro-panel-head"><h2>Зар тус бүрийн үзүүлэлт</h2></div><div class="pro-table-wrap"><table class="pro-table"><thead><tr><th>Зар</th><th>Төлөв</th><th>Үзэлт</th><th>Энэ браузерт хадгалсан</th><th>Лавлагаа</th></tr></thead><tbody>${own.map(h=>`<tr><td><b>${esc(h.name)}</b><p>№ ${h.id}</p></td><td>${proStatusBadge(h.listingStatus||'published')}</td><td>${p.activities.filter(e=>e.type==='view'&&e.listingId===h.id).length}</td><td>${saved.includes(h.id)?1:0}</td><td>${inquiries.filter(r=>r.propertyId===h.id).length}</td></tr>`).join('')}</tbody></table></div>${!own.length?proEmpty('Үзүүлэлт бүртгэгдээгүй','Зараа нийтэлсний дараа хэрэглэгчийн хуудсан дээрх үйлдлүүд бүртгэгдэнэ.'):''}</section><section class="pro-panel"><div class="pro-panel-head"><h2>Зах зээлийн мэдээллийн холболт</h2></div><p class="pro-note">Монголын бодит хэлцэл болон бусад платформын мэдээллийн эх сурвалж холбогдоогүй. Энд бүртгэсэн өөрийн зарын мэдээллээр тайлан гаргана.</p></section>`}
function proSettings(){const office=proState().office;return `${proHeading('БАЙГУУЛЛАГЫН МЭДЭЭЛЭЛ','Байгууллагын мэдээлэл','Шинэ зарын зуучлагчийн мэдээллийг урьдчилан бөглөхөд ашиглана.')}<section class="pro-panel pro-settings"><div class="pro-panel-head"><h2>Миний байгууллага</h2>${icon('briefcase')}</div><form onsubmit="proSaveOffice(event)"><div class="pro-form-grid">${[['name','Байгууллагын нэр','text',true],['agent','Зуучлагчийн нэр','text'],['phone','Холбоо барих утас','tel'],['email','Байгууллагын имэйл','email'],['address','Байгууллагын хаяг','text'],['registration','Байгууллагын улсын бүртгэлийн дугаар','text'],['licenseNumber','Зуучлалын зөвшөөрлийн дугаар','text'],['licenseValidUntil','Зөвшөөрөл хүчинтэй хүртэл','date']].map(f=>proField(f,office)).join('')}</div><p class="pro-form-error" role="alert"></p><div class="flow-actions"><button class="primary">Мэдээлэл хадгалах</button></div></form><a class="pro-admin-demo-link" href="#/pro/office">${icon('briefcase')}Нийтийн профайлын мэдээлэл засах ${icon('arrow-up-right')}</a></section>${brokerProPanel()}<section class="pro-panel"><h2>Ажлын орчны эрх</h2><p class="pro-note">Одоогийн хувилбар нь нэг браузерын демо ажлын орчин. Серверийн нэвтрэлт, байгууллага тус бүрийн эрх, багийн бодит хуваалцах үйлчилгээ хараахан холбогдоогүй.</p><a class="pro-admin-demo-link" href="#/admin">${icon('shield')}Платформын удирдлагын демо ${icon('arrow-up-right')}</a></section>`}
function proSaveOffice(event){event.preventDefault();const f=new FormData(event.target),office=Object.fromEntries(['name','agent','phone','email','address','registration','licenseNumber','licenseValidUntil'].map(k=>[k,String(f.get(k)||'').trim()]));if(!office.name){event.target.querySelector('.pro-form-error').textContent='Байгууллагын нэр оруулна уу.';return}if(office.phone&&!/^\+?[\d\s()-]{8,25}$/.test(office.phone)){event.target.querySelector('.pro-form-error').textContent='Утасны дугаараа шалгана уу.';return}proMutate(p=>p.office=office,'Байгууллагын мэдээлэл хадгалагдлаа')}
function proSeedWorkspace(){const p=proState();if(p.clients.some(c=>c.sample)){toast('Жишээ ажлын мэдээлэл аль хэдийн байна');return}proMutate(p=>{const a={id:flowId(),name:'Жишээ · Бат',phone:'',kind:'tenant',stage:'new',area:'Хан-Уул',budgetMax:2500000,note:'Жишээ харилцагч · 2–3 өрөө сонирхож байна',sample:true},b={id:flowId(),name:'Жишээ · Саруул',phone:'',kind:'buyer',stage:'progress',area:'Баянзүрх',budgetMax:250000000,note:'Жишээ харилцагч · Худалдан авах хүсэлт',sample:true};p.clients.push(a,b);p.schedules.push({id:flowId(),name:'Жишээ · Байр үзүүлэхээр ярилцах',date:proToday(),time:'14:00',clientId:a.id,stage:'planned',kind:'call',note:'Зөвхөн ажлын урсгалын жишээ',sample:true});p.consultations.push({id:flowId(),name:'Жишээ · Хүсэлтийн тэмдэглэл',clientId:a.id,stage:'new',note:'Гэрэл сайтай, сургуульд ойр байр хайж байна.',sample:true});p.ledger.push({id:flowId(),name:'Жишээ · Анхны хувийн тэмдэглэл',area:'Хан-Уул',address:'Жишээ хаяг',price:2500000,note:'Олон нийтэд харагдахгүй хувийн бүртгэлийн жишээ.',sample:true})},'Жишээ ажлын мэдээлэл нэмэгдлээ')}
function proCsvValue(value){let s=String(value??'').replace(/[\r\n]+/g,' ');if(/^[\s]*[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function proCsv(kind){const rows=kind==='activities'?proActivities():proState()[kind];if(!Array.isArray(rows))return '';const fields=kind==='activities'?[['date','Огноо'],['type','Үйлдлийн төрөл'],['listingId','Холбоотой зар','listing'],['label','Тайлбар']]:(PRO_SCHEMAS[kind]?.fields.filter(f=>!f[0].startsWith('newClient'))||[]);return '\uFEFF'+[fields.map(f=>f[1]),...rows.map(item=>fields.map(([key,,type,,options])=>type==='client'?proClientName(item[key]):type==='listing'?proListingName(item[key]):type==='select'?options.find(([value])=>value===item[key])?.[1]||item[key]:Array.isArray(item[key])?item[key].map(proListingName).join('; '):item[key]))].map(row=>row.map(proCsvValue).join(',')).join('\r\n')}
function proExport(kind){const csv=proCsv(kind);if(!csv)return;const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='oroo-pro-'+kind+'-'+proToday()+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function proPrintContract(id){const item=proState().contracts.find(c=>c.id===id);if(!item)return;modal(`<article class="pro-print-record"><span>ӨРӨӨ PRO · АЖЛЫН БҮРТГЭЛ</span><h2>${esc(item.name)}</h2><p class="notice">Энэ нь ажлын тэмдэглэл. Гарын үсэгтэй гэрээ, хууль зүйн маягт биш.</p>${listingRows([['Харилцагч',proClientName(item.clientId)],['Зар',proListingName(item.listingId)],['Үндсэн үнэ',formatMnt(item.amount)],['Барьцаа',formatMnt(item.deposit)],['Эхлэх огноо',item.startDate],['Дуусах огноо',item.endDate],['Төлбөрийн тов',item.paymentDate],['Төлөв',PRO_STATUS[item.stage]]])}<p class="listing-user-text">${esc(item.note||'')}</p><button class="primary" onclick="window.print()">${icon('printer')}Хэвлэх</button></article>`);document.querySelector('.modal').classList.add('pro-print-modal')}
function syncPlatformStorage(event){if(!['mn-flows','mn-saved','mn-recent'].includes(event.key))return;const path=location.hash||'#/';if(path.startsWith('#/listing/')||path.startsWith('#/pro/new'))return;if(event.key==='mn-flows'){const incoming=readFlowState();for(const key of ['searches','bookmarks','complexSaved','complexRecent','requests','reports','posts','listings'])flowState[key]=Array.isArray(incoming[key])?incoming[key]:[];flowState.profile=incoming.profile||{name:'Зочин',demo:false};flowState.pro=incoming.pro||{};flowState.admin=incoming.admin||{};flowState.neighborhood=incoming.neighborhood||{};flowState.draft=incoming.draft||{};editorReady=false;for(let i=homes.length-1;i>=0;i--)if(homes[i].local)homes.splice(i,1);hydrateLocalListings();if(activeDetail&&!isPublicListing(homes.find(h=>h.id===activeDetail))){activeDetail=null;closeOverlay()}const galleryId=document.querySelector('[data-gallery-listing]')?.dataset?.galleryListing;if(galleryId&&!isPublicListing(homes.find(h=>h.id===Number(galleryId))))closeOverlay()}else{let values=[];try{values=JSON.parse(localStorage.getItem(event.key)||'[]')}catch{}if(!Array.isArray(values))values=[];if(event.key==='mn-saved')saved=values;else recent=values}render()}
window.addEventListener('storage',syncPlatformStorage);
